// Why Code: the query is a UNION of one pending check per template in the plan, which comes from settings.
const s = $('Conductor settings').first().json;
const checks = (s.stages || []).flatMap(st => st.steps || []).map(x => x.pending).filter(Boolean);
const ids = $('Get open products').all().map(i => String(i.json.product_id).replace(/\D/g, ''));
const sql = checks.length
  ? `select distinct regexp_replace(product_id::text, '\\D', '', 'g') as pid from (${checks.map(c => `(${c})`).join(' union all ')}) x where regexp_replace(product_id::text, '\\D', '', 'g') = any($1::text[])`
  : 'select null::text as pid where false and $1::text[] is not null';
return [{ json: { sql, ids } }];

// Why Code: each product's next stage depends on its tags, its pending rows and its age in the stage; no native node holds that state machine.
const s = $('Conductor settings').first().json;
const stages = (s.stages || []).filter(st => (st.steps || []).length);
const live = Object.fromEntries(($('Read their tags').first().json.data?.nodes || []).filter(Boolean).map(p => [p.id, p]));
const waiting = new Set($input.all().map(i => i.json.pid).filter(Boolean));
const dayMs = 86400000;
return $('Get open products').all().map(i => i.json).filter(r => r.product_id).map(r => {
  const p = live[r.product_id];
  const base = { product_id: r.product_id, title: r.title, stage: r.stage, stage_name: r.stage_name, add_tags: [], moved: false, done: false, note: null };
  if (!p || p.status !== 'ACTIVE') return { json: { ...base, done: true, moved: true, note: 'no longer live' } };
  let next = r.stage + 1;
  if (r.stage > 0) {
    const cur = stages[r.stage - 1];
    const left = cur ? cur.steps.map(x => x.tag).filter(t => p.tags.includes(t)) : [];
    const busy = left.length || waiting.has(String(r.product_id).replace(/\D/g, ''));
    const stuck = Date.now() - new Date(r.stage_started_at).getTime() > s.max_stage_days * dayMs;
    if (busy && !stuck) return { json: base };
    if (busy) base.note = `moved on after ${s.max_stage_days} days in ${r.stage_name}` + (left.length ? ` (still tagged ${left.join(', ')})` : ' (still waiting in Slack)');
  }
  if (next > stages.length) return { json: { ...base, stage: next, stage_name: 'done', done: true, moved: true } };
  const st = stages[next - 1];
  return { json: { ...base, stage: next, stage_name: st.stage, add_tags: st.steps.map(x => x.tag).filter(t => !p.tags.includes(t)), moved: true } };
});
